/// <summary>
/// Extension of DirPartyQuickCreateForm
/// </summary>
[ExtensionOf(formStr(DirPartyQuickCreateForm))]
final class METDirPartyQuickCreateForm_Extension
{
}

Method.Source:
    /// <summary>
    /// run the DirPartyQuickCreateForm
    /// </summary>
    public void run()
    {
        Args            args = new Args();
        Form            form = new Form(formStr(DirPartyQuickCreateForm));
        CustAccount     custAccount ;
        FormRun         fr = this as  FormRun;
        FormDataSource  dirPartyEntity_ds = fr.dataSource(formDataSourceStr(DirPartyQuickCreateForm, DirPartyEntity)) as FormDataSource;
        CustTable       custTable = dirPartyEntity_ds.cursor();

        args.caller(fr);
        args.object(form);
        args.record(custTable);

        if (curExt() == "@MET:METFood" || curExt() == "@MET:METLIQ" || curExt() == "@MET:METHWE")
        {
            custAccount = METCreateCustNumSeqDialog::main(args);
        }
       
        next run();
        
        if (curExt() == "@MET:METFood" || curExt() == "@MET:METLIQ" || curExt() == "@MET:METHWE")
        {
            custTable.AccountNum = custAccount;
        }
    }
